import dev.netlens.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Tests the network-input and identity defects established in the discovery investigation. */
public final class DiscoveryUpgradeTest {
    private static int checks;
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static void name(DataOutputStream out,String name)throws Exception{for(String label:name.split("\\.")){byte[] b=label.getBytes(StandardCharsets.UTF_8);out.writeByte(b.length);out.write(b);}out.writeByte(0);}
    private static byte[] reply(String owner,String target,long ttl,int cls)throws Exception{
        ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.writeShort(0);out.writeShort(0x8400);out.writeShort(0);out.writeShort(1);out.writeInt(0);name(out,owner);out.writeShort(12);out.writeShort(cls);out.writeInt((int)ttl);ByteArrayOutputStream r=new ByteArrayOutputStream();name(new DataOutputStream(r),target);out.writeShort(r.size());out.write(r.toByteArray());return b.toByteArray();
    }
    private static boolean empty(MdnsPacket.Result r){return r.serviceTypes.isEmpty()&&r.hostnames.isEmpty();}
    public static void main(String[] args)throws Exception{
        for(int order=0;order<2;order++){
            IdentityHints hints=new IdentityHints();if(order==0)hints.offer("Name","Living room TV","UPnP",80);hints.offer("Name","Android","mDNS friendly",90);if(order==1)hints.offer("Name","Living room TV","UPnP",80);
            check(hints.offer("Name","Device","fallback",99).value.equals("Living room TV"),"Specific name beats higher-priority generic values in both orders");
            hints.offer("Model","Useful Model 500","UPnP",70);check(hints.offer("Model","Unknown","TXT",80).value.equals("Useful Model 500"),"Unknown model cannot replace useful metadata");
            check(hints.observations().stream().anyMatch(h->h.value.equals("Unknown")),"Conflicting generic evidence remains available");
        }
        for(String generic:new String[]{"192.168.1.2","fd00::1","00:11:22:33:44:55","001122334455","android_aabbccddeeff","ESP_3A2F1C","n/a","unknown model"}){
            IdentityHints h=new IdentityHints();h.offer("Name",generic,"strong source",95);check(h.offer("Name","Office printer","useful source",30).value.equals("Office printer"),"Raw addresses/generated names are fallbacks: "+generic);
        }
        IdentityHints h=new IdentityHints();check(h.offer("Name","Android","only source",90).value.equals("Android"),"Generic fallback is retained when nothing else exists");
        h.offer("Model","Explicit model","TXT",80);check(h.offer("Model","Compatibility string","device-info",20).value.equals("Explicit model"),"Source rank still selects between specific values");
        IdentityHints own=new IdentityHints();own.offer("Model","Unknown","This phone",100);check(own.offer("Model","External claim","network",80).value.equals("Unknown"),"This phone platform identity stays authoritative");
        ServiceAdmission budget=new ServiceAdmission(4,2);check(budget.reserve("a","http")&&budget.reserve("b","http"),"First type receives its fair share");check(budget.admit("c","http")==ServiceAdmission.Result.LIMIT,"Chatty type is capped");check(budget.reserve("printer","ipp")&&budget.reserve("audio","raop"),"Other types retain capacity");check(budget.admit("a","http")==ServiceAdmission.Result.DUPLICATE&&budget.size()==4,"Duplicates consume no additional capacity");check(budget.admit("fifth","ssh")==ServiceAdmission.Result.LIMIT,"Total safety cap remains");
        DiscoveryHealth health=new DiscoveryHealth();health.starting("http");health.started("http");health.resolving("slow","http");health.truncated("mDNS http","Per-type limit reached");health.finish(false);String state=health.sources().get("mDNS http");check(state.contains("Per-type limit")&&state.contains("did not finish"),"Cleanup preserves earlier limit reason");health.ok("mDNS http");check(!health.summary().isEmpty(),"Success cannot erase a limit");health.fail("mDNS http","Permission denied");check(health.sources().get("mDNS http").startsWith("Failed"),"Failure remains stronger than truncation");health.count("mDNS http","found");health.count("mDNS http","found");check(health.sources().get("mDNS http").contains("found 2"),"Private source counters are retained");
        DescriptionQueue descriptions=new DescriptionQueue(1,3);URI first=new URI("http://192.168.1.2/bad.xml"),second=new URI("http://192.168.1.2/good.xml"),third=new URI("http://192.168.1.2/other.xml");
        check(descriptions.offer("peer",first)==DescriptionQueue.Offer.START,"First description schedules a worker");check(descriptions.next("peer").equals(first),"Worker receives first eligible location");descriptions.record("peer",false);check(descriptions.offer("peer",second)==DescriptionQueue.Offer.QUEUED,"Failure does not exclude an alternative");check(descriptions.next("peer").equals(second),"Alternative is serialized behind first request");descriptions.record("peer",true);check(descriptions.next("peer")==null&&descriptions.failedPeers()==0,"Fallback success clears final peer failure");check(descriptions.offer("peer",second)==DescriptionQueue.Offer.DUPLICATE,"Duplicate descriptions are not fetched again");check(descriptions.offer("peer",third)==DescriptionQueue.Offer.START,"A later new opportunity restarts a drained worker");check(descriptions.offer("peer",new URI("http://192.168.1.2/four.xml"))==DescriptionQueue.Offer.LIMIT&&descriptions.offer("other",first)==DescriptionQueue.Offer.LIMIT,"Per-peer and total peer limits remain bounded");descriptions.next("peer");descriptions.record("peer",false);descriptions.next("peer");check(descriptions.failedPeers()==0,"A later failed alternative cannot hide earlier valid metadata");
        check(MdnsPacket.serviceType("_MieleAtHome._TCP.local.").equals("_mieleathome._tcp."),"Normalize dynamically advertised service type");
        for(String invalid:new String[]{"http._tcp.local","_http._tcp.evil.com","_http._tcp.local.evil","_x._sub._http._tcp.local","_http._tcp.local\u202e","_http._tcp.local/"})check(MdnsPacket.serviceType(invalid).isEmpty(),"Reject unqualified/outside/ambiguous type");
        byte[] packet=reply(MdnsPacket.ENUMERATION,"_mieleathome._tcp.local",120,1);check(MdnsPacket.parse(packet,packet.length).serviceTypes.contains("_mieleathome._tcp."),"Read enumeration PTR response");
        byte[] reverse=reply(ReverseDns.question("192.168.1.20"),"office.local",120,0x8001);check("office.local".equals(MdnsPacket.parse(reverse,reverse.length).hostnames.get("20.1.168.192.in-addr.arpa")),"Read reverse PTR and mask cache-flush bit");
        ByteArrayOutputStream compressedBytes=new ByteArrayOutputStream();DataOutputStream compressedOut=new DataOutputStream(compressedBytes);compressedOut.write(new byte[]{0,0,(byte)0x84,0,0,1,0,1,0,0,0,0});name(compressedOut,MdnsPacket.ENUMERATION);compressedOut.writeShort(12);compressedOut.writeShort(1);compressedOut.writeShort(0xc00c);compressedOut.writeShort(12);compressedOut.writeShort(1);compressedOut.writeInt(120);ByteArrayOutputStream targetBytes=new ByteArrayOutputStream();DataOutputStream targetOut=new DataOutputStream(targetBytes);name(targetOut,"_mieleathome._tcp.local");compressedOut.writeShort(targetBytes.size());compressedOut.write(targetBytes.toByteArray());byte[] compressed=compressedBytes.toByteArray();check(MdnsPacket.parse(compressed,compressed.length).serviceTypes.contains("_mieleathome._tcp."),"Compressed owner can point back to the question name");
        ByteArrayOutputStream mixedBytes=new ByteArrayOutputStream();DataOutputStream mixedOut=new DataOutputStream(mixedBytes);mixedOut.write(packet);name(mixedOut,"Living room._http._tcp.local");mixedOut.writeShort(16);mixedOut.writeShort(1);mixedOut.writeInt(120);mixedOut.writeShort(3);mixedOut.write(new byte[]{2,120,121});byte[] mixed=mixedBytes.toByteArray();mixed[11]=1;check(MdnsPacket.parse(mixed,mixed.length).serviceTypes.contains("_mieleathome._tcp."),"Unrelated non-hostname additional record does not discard a useful PTR");
        byte[] goodbye=reply(MdnsPacket.ENUMERATION,"_mieleathome._tcp.local",0,1);check(empty(MdnsPacket.parse(goodbye,goodbye.length)),"Ignore goodbye TTL zero");byte[] otherClass=reply(MdnsPacket.ENUMERATION,"_mieleathome._tcp.local",120,3);check(empty(MdnsPacket.parse(otherClass,otherClass.length)),"Ignore non-IN records");byte[] outside=reply(ReverseDns.question("192.168.1.20"),"external.example",120,1);check(empty(MdnsPacket.parse(outside,outside.length)),"Only local reverse names accepted");
        byte[] arbitrary=reply("Living room._http._tcp.local","Other room._http._tcp.local",120,1);check(empty(MdnsPacket.parse(arbitrary,arbitrary.length)),"Unrelated instance records do not become hostnames or service types");
        for(int i=0;i<packet.length;i++)check(empty(MdnsPacket.parse(packet,i)),"Every truncated enumeration reply rejected");
        byte[] bad=packet.clone();bad[1]=1;check(empty(MdnsPacket.parse(bad,bad.length)),"Ignore nonzero mDNS transaction IDs");bad=packet.clone();bad[2]|=2;check(empty(MdnsPacket.parse(bad,bad.length)),"Reject DNS truncation flag");bad=packet.clone();bad[12]=(byte)0xc0;bad[13]=12;check(empty(MdnsPacket.parse(bad,bad.length)),"Reject cyclic compression pointer");bad=packet.clone();bad[6]=127;check(empty(MdnsPacket.parse(bad,bad.length)),"Bound resource-record counts");check(empty(MdnsPacket.parse(new byte[8193],8193)),"Bound packet size");
        byte[] query=MdnsPacket.query(Arrays.asList(MdnsPacket.ENUMERATION,ReverseDns.question("192.168.1.20")));check(query[0]==0&&query[1]==0&&query[5]==2&&query.length<1200,"Generate bounded, nonrecursive multicast questions");
        for(String invalid:new String[]{"example.com","evil..in-addr.arpa", "x\r\n.in-addr.arpa"}){try{MdnsPacket.query(Collections.singletonList(invalid));throw new AssertionError("Invalid question accepted");}catch(IllegalArgumentException expected){check(true,"Reject unrelated or malformed questions");}}
        try{MdnsPacket.query(Collections.nCopies(9,MdnsPacket.ENUMERATION));throw new AssertionError("Oversized question batch");}catch(IllegalArgumentException expected){check(true,"Bound question count");}
        Random random=new Random(28);for(int i=0;i<20000;i++){byte[] fuzz=new byte[random.nextInt(8194)];random.nextBytes(fuzz);MdnsPacket.parse(fuzz,fuzz.length);}check(true,"20,000 malformed mDNS packets cannot crash parsing");
        System.out.println("PASS · "+checks+" discovery-upgrade assertions and 20,000 malformed mDNS inputs");
    }
}
